// func dequantRowScaledAVX512(dst []float32, data []byte, scales *float32, rowOff, nBlocks int)
// Single-row Q8→f32 with f32 scale cache. Frame matches AVX2 (72 bytes).
TEXT ·dequantRowScaledAVX512(SB), NOSPLIT, $0-72
	MOVQ dst+0(FP), SI
	MOVQ data+24(FP), DI
	MOVQ scales+48(FP), R8
	ADDQ rowOff+56(FP), DI
	MOVQ nBlocks+64(FP), CX
	TESTQ CX, CX
	JZ   dqs1_512_done

	MOVQ CX, R10
	SHRQ $1, R10
	TESTQ R10, R10
	JZ   dqs1_512_one

dqs1_512_loop2:
	PREFETCHT0 136(DI)
	PREFETCHT0 256(SI)
	VBROADCASTSS (R8), Z1
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 18(DI), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z1, Z2, Z2
	VMULPS Z1, Z3, Z3
	VMOVUPS Z2, 0(SI)
	VMOVUPS Z3, 64(SI)
	VBROADCASTSS 4(R8), Z1
	VPMOVSXBD 36(DI), Z2
	VPMOVSXBD 52(DI), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z1, Z2, Z2
