// func dotQ8RowScaledAVX512(a *float32, data *byte, scales *float32, rowOff, nBlocks int) float32
// Single-row Q8 scaled dot, 16-wide (SenseVoice M remainder / M=1).
// Frame: a+0 data+8 scales+16 rowOff+24 nBlocks+32 ret+40 → 48
TEXT ·dotQ8RowScaledAVX512(SB), NOSPLIT, $0-48
	MOVQ a+0(FP), SI
	MOVQ data+8(FP), DI
	MOVQ scales+16(FP), R8
	ADDQ rowOff+24(FP), DI
	MOVQ nBlocks+32(FP), CX
	VXORPS Z0, Z0, Z0
	TESTQ CX, CX
	JZ   dqs512_dot_done

dqs512_dot_loop:
	PREFETCHT0 68(DI)
	PREFETCHT0 256(SI)
	VBROADCASTSS (R8), Z1
	ADDQ $4, R8
	// half0: bytes 2..17 → 16 floats
	VPMOVSXBD 2(DI), Z2
	VCVTDQ2PS Z2, Z2
	VMULPS Z1, Z2, Z2
	VMOVUPS (SI), Z3
	VFMADD231PS Z3, Z2, Z0
	// half1: bytes 18..33
	VPMOVSXBD 18(DI), Z2
	VCVTDQ2PS Z2, Z2
	VMULPS Z1, Z2, Z2
	VMOVUPS 64(SI), Z3
	VFMADD231PS Z3, Z2, Z0
	ADDQ $34, DI
	ADDQ $128, SI
	DECQ CX
	JNZ  dqs512_dot_loop

dqs512_dot_done:
	VEXTRACTF32X8 $1, Z0, Y1
	VADDPS Y0, Y1, Y0
	VEXTRACTF32X4 $1, Y0, X1
	VADDPS X0, X1, X0
	VSHUFPD $1, X0, X0, X1
	VADDPS X0, X1, X0
	VMOVSHDUP X0, X1
	VADDSS X0, X1, X0
	MOVSS X0, ret+40(FP)
	VZEROUPPER
	RET

// func q8DualDot2ScaledAVX512(out *[2]float32, a *float32, data *byte, scales0, scales1 *float32, rowOff0, rowOff1, nBlocks int)
// Dual-B Q8 scaled dots sharing A stream (M remainder / M=1 dual).
// Frame: out+0 a+8 data+16 s0+24 s1+32 off0+40 off1+48 nBlocks+56 → 64
TEXT ·q8DualDot2ScaledAVX512(SB), NOSPLIT, $0-64
	MOVQ out+0(FP), R11
	MOVQ a+8(FP), SI
	MOVQ data+16(FP), DI
	MOVQ scales0+24(FP), R8
	MOVQ scales1+32(FP), R9
	MOVQ nBlocks+56(FP), CX
	ADDQ rowOff0+40(FP), DI
	MOVQ data+16(FP), R15
	ADDQ rowOff1+48(FP), R15
	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	TESTQ CX, CX
	JZ   ddsc512_hsum

ddsc512_loop:
	PREFETCHT0 68(DI)
	PREFETCHT0 68(R15)
	PREFETCHT0 256(SI)
	VBROADCASTSS (R8), Z30
	VBROADCASTSS (R9), Z31
	ADDQ $4, R8
	ADDQ $4, R9
	// half0
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 2(R15), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z30, Z2, Z2
	VMULPS Z31, Z3, Z3
	VMOVUPS (SI), Z4
	VFMADD231PS Z4, Z2, Z0
	VFMADD231PS Z4, Z3, Z1
	// half1
	VPMOVSXBD 18(DI), Z2
	VPMOVSXBD 18(R15), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z30, Z2, Z2
	VMULPS Z31, Z3, Z3
	VMOVUPS 64(SI), Z4
	VFMADD231PS Z4, Z2, Z0
	VFMADD231PS Z4, Z3, Z1
	ADDQ $34, DI
	ADDQ $34, R15
	ADDQ $128, SI
	DECQ CX
	JNZ  ddsc512_loop

ddsc512_hsum:
	VEXTRACTF32X8 $1, Z0, Y2
	VADDPS Y0, Y2, Y0
	VEXTRACTF32X4 $1, Y0, X2
	VADDPS X0, X2, X0
	VSHUFPD $1, X0, X0, X2
	VADDPS X0, X2, X0
	VMOVSHDUP X0, X2
	VADDSS X0, X2, X0
	MOVSS X0, (R11)

	VEXTRACTF32X8 $1, Z1, Y2
	VADDPS Y1, Y2, Y1
	VEXTRACTF32X4 $1, Y1, X2
	VADDPS X1, X2, X1
	VSHUFPD $1, X1, X1, X2
	VADDPS X1, X2, X1
	VMOVSHDUP X1, X2
	VADDSS X1, X2, X1
	MOVSS X1, 4(R11)

	VZEROUPPER
	RET

// func wsumBatched8Add128DualAVX512(o0,o1,o2,o3,o4,o5,o6,o7, va, vb, wa, wb *float32)
// out_t += wa[t]*va + wb[t]*vb, dim=128, 16-wide.
// Frame: o0+0..o7+56 va+64 vb+72 wa+80 wb+88 → 96
TEXT ·wsumBatched8Add128DualAVX512(SB), NOSPLIT, $0-96
	MOVQ o0+0(FP), R8
