	MOVQ o6+48(FP), R14
	MOVQ o7+56(FP), R15
	MOVQ va+64(FP), SI
	MOVQ vb+72(FP), DI
	MOVQ wa+80(FP), AX
	MOVQ wb+88(FP), BX
	VMOVSS 0(AX), X0
	VBROADCASTSS X0, Z16
	VMOVSS 4(AX), X0
	VBROADCASTSS X0, Z17
	VMOVSS 8(AX), X0
	VBROADCASTSS X0, Z18
	VMOVSS 12(AX), X0
	VBROADCASTSS X0, Z19
	VMOVSS 16(AX), X0
	VBROADCASTSS X0, Z20
	VMOVSS 20(AX), X0
