	VMOVSS 24(AX), X0
	VBROADCASTSS X0, Z22
	VMOVSS 28(AX), X0
	VBROADCASTSS X0, Z23
	VMOVSS 0(BX), X0
	VBROADCASTSS X0, Z24
	VMOVSS 4(BX), X0
	VBROADCASTSS X0, Z25
	VMOVSS 8(BX), X0
	VBROADCASTSS X0, Z26
	VMOVSS 12(BX), X0
	VBROADCASTSS X0, Z27
	VMOVSS 16(BX), X0
	VBROADCASTSS X0, Z28
	VMOVSS 20(BX), X0
	VBROADCASTSS X0, Z29
	VMOVSS 24(BX), X0
	VBROADCASTSS X0, Z30
	VMOVSS 28(BX), X0
	VBROADCASTSS X0, Z31

	MOVQ $8, CX
wsum8_loop:
	VMOVUPS (SI), Z0
	VMOVUPS (DI), Z1
	VMOVUPS (R8), Z2
	VFMADD231PS Z0, Z16, Z2
	VFMADD231PS Z1, Z24, Z2
	VMOVUPS Z2, (R8)
	VMOVUPS (R9), Z2
	VFMADD231PS Z0, Z17, Z2
	VFMADD231PS Z1, Z25, Z2
	VMOVUPS Z2, (R9)
	VMOVUPS (R10), Z2
	VFMADD231PS Z0, Z18, Z2
	VFMADD231PS Z1, Z26, Z2
	VMOVUPS Z2, (R10)
	VMOVUPS (R11), Z2
	VFMADD231PS Z0, Z19, Z2
	VFMADD231PS Z1, Z27, Z2
	VMOVUPS Z2, (R11)
	VMOVUPS (R12), Z2
	VFMADD231PS Z0, Z20, Z2
	VFMADD231PS Z1, Z28, Z2
	VMOVUPS Z2, (R12)
	VMOVUPS (R13), Z2
	VFMADD231PS Z0, Z21, Z2
	VFMADD231PS Z1, Z29, Z2
	VMOVUPS Z2, (R13)
	VMOVUPS (R14), Z2
	VFMADD231PS Z0, Z22, Z2
	VFMADD231PS Z1, Z30, Z2
	VMOVUPS Z2, (R14)
	VMOVUPS (R15), Z2
	VFMADD231PS Z0, Z23, Z2
	VFMADD231PS Z1, Z31, Z2
	VMOVUPS Z2, (R15)
	ADDQ $64, SI
	ADDQ $64, DI
	ADDQ $64, R8
	ADDQ $64, R9
	ADDQ $64, R10
	ADDQ $64, R11
	ADDQ $64, R12
	ADDQ $64, R13
	ADDQ $64, R14
	ADDQ $64, R15
	DECQ CX
	JNZ  wsum8_loop
	VZEROUPPER
	RET
